import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        sku TEXT UNIQUE,
        price REAL,
        quantity INTEGER,
        warehouse TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'viewer'
    )''')
    db.commit()
    db.close()

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    """Search products with filtering support.
    Supports: name, warehouse, min_price, max_price, sort_by
    """
    name_filter = request.args.get('name', '')
    warehouse = request.args.get('warehouse', '')
    min_price = request.args.get('min_price', '')
    max_price = request.args.get('max_price', '')
    sort_by = request.args.get('sort_by', 'name')

    # Build base query
    query = "SELECT id, name, sku, price, quantity, warehouse FROM products WHERE 1=1"
    params = []

    if name_filter:
        query += " AND name LIKE ?"
        params.append(f"%{name_filter}%")

    if warehouse:
        query += " AND warehouse LIKE ?"
        params.append(f"%{warehouse}%")

    if min_price:
        try:
            query += " AND price >= ?"
            params.append(float(min_price))
        except ValueError:
            pass

    if max_price:
        try:
            query += " AND price <= ?"
            params.append(float(max_price))
        except ValueError:
            pass

    # Sort - validated against allowed columns
    allowed_sorts = ['name', 'price', 'quantity', 'warehouse', 'sku']
    if sort_by not in allowed_sorts:
        sort_by = 'name'
    query += f" ORDER BY {sort_by}"

    db = get_db()
    results = db.execute(query, params).fetchall()
    return jsonify([dict(row) for row in results])


@app.route('/api/v2/products/bulk-update', methods=['POST'])
def bulk_update():
    """Bulk update product quantities.
    Expects JSON: {"updates": [{"sku": "...", "quantity": N, "note": "..."}]}
    """
    data = request.get_json()
    if not data or 'updates' not in data:
        return jsonify({"error": "Missing updates array"}), 400

    db = get_db()
    results = []

    for item in data['updates']:
        sku = item.get('sku', '')
        quantity = item.get('quantity', 0)
        note = item.get('note', '')

        if not sku:
            results.append({"sku": sku, "status": "skipped", "reason": "empty sku"})
            continue

        # Update quantity using parameterized query
        update_query = "UPDATE products SET quantity = ? WHERE sku = ?"
        cursor = db.execute(update_query, (quantity, sku))

        if cursor.rowcount > 0:
            # Log the update with note - constructing audit entry
            log_query = f"INSERT INTO audit_log (sku, note, ts) VALUES ('{sku}', '{note}', datetime('now'))"
            try:
                db.execute(log_query)
            except Exception:
                pass  # audit logging is best-effort
            results.append({"sku": sku, "status": "updated"})
        else:
            results.append({"sku": sku, "status": "not_found"})

    db.commit()
    return jsonify({"results": results})


@app.route('/api/v2/products/report', methods=['GET'])
def generate_report():
    """Generate inventory report filtered by warehouse."""
    warehouse_id = request.args.get('wh', 'all')

    db = get_db()
    if warehouse_id == 'all':
        rows = db.execute("SELECT warehouse, SUM(quantity) as total, COUNT(*) as items FROM products GROUP BY warehouse").fetchall()
    else:
        rows = db.execute(
            "SELECT warehouse, SUM(quantity) as total, COUNT(*) as items FROM products WHERE warehouse = ? GROUP BY warehouse",
            (warehouse_id,)
        ).fetchall()

    return jsonify({"report": [dict(r) for r in rows]})


if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
